SourceCode.Declaration:
/// <summary>
/// This is an extension class for VendEditInvoice form MetPerformMatching control.
/// </summary>
[ExtensionOf(formControlStr(VendEditInvoice, MetPerformMatching))]
final class METVendEditInvoicePerformMatchingCtrl_Extension
{
}

Method.Source:
    /// <summary>
/// Reset the custom match status on the vendor invoice form.
/// </summary>
public void clicked()
{
    next clicked();

    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        FormControl performMatching = this;

        FormDataSource vendInvInfoTable = performMatching.formRun().dataSource(formDataSourceStr(VendEditInvoice, VendInvoiceInfoTable));
        VendInvoiceInfoTable vendInvoiceInfoTable = vendInvInfoTable.cursor();

        if (!vendInvoiceInfoTable.isChargeThroughEnabled() && !vendInvoiceInfoTable.isLandedCostEnabled())
        {
            vendInvInfoTable.executeQuery();
        }
    }
}
